import bpy, math, os
from mathutils import Vector

# remove hidden old eye spheres
for n in ["EyeballL","EyeballR","PupilL","PupilR"]:
    if n in bpy.data.objects: bpy.data.objects.remove(bpy.data.objects[n], do_unlink=True)

# convert curves (arms, texts) to mesh
bpy.ops.object.select_all(action='DESELECT')
for o in bpy.data.objects:
    if o.type in ('CURVE','FONT'):
        o.select_set(True); bpy.context.view_layer.objects.active=o
        bpy.ops.object.convert(target='MESH')
        bpy.ops.object.select_all(action='DESELECT')

scene=bpy.context.scene
scene.render.resolution_x=1100; scene.render.resolution_y=1100
def look_at(obj, target):
    dv=Vector(target)-obj.location; obj.rotation_euler=dv.to_track_quat('-Z','Y').to_euler()
cam=bpy.data.objects["Camera"]; cam.data.lens=42

views=[("output/robie_hero.png",(3.4,-5.0,2.9)),("output/robie_front.png",(0,-6.0,1.7)),("output/robie_back_top.png",(3.6,4.6,4.4))]
for path,loc in views:
    cam.location=loc; look_at(cam,(0,0,1.05)); scene.render.filepath=path; bpy.ops.render.render(write_still=True)

# export GLB: robot only
exclude={"Ground","Camera"}
bpy.ops.object.select_all(action='DESELECT')
count=0
for o in bpy.data.objects:
    if o.name in exclude or o.type in ('CAMERA','LIGHT'):
        o.hide_set(False)
        continue
    o.select_set(True); count+=1
bpy.context.view_layer.objects.active=bpy.data.objects["Body"]
os.makedirs("output", exist_ok=True)
bpy.ops.export_scene.gltf(filepath=os.path.abspath("output/robie_the_banker.glb"), export_format='GLB', use_selection=True, export_apply=True)

# cleanup previews
for p in ["output/preview1.png","output/preview_front.png","output/preview_back.png"]:
    if os.path.exists(p): os.remove(p)
import pathlib
result={"ok":True,"exported":count,"files":[(f.name, f.stat().st_size) for f in pathlib.Path("output").iterdir()]}
